	let useCapture;
	let nameLower;
	let proxy;
	let prevStyle;
	let nextStyle;
	let styleName;
	let styleValue;
	let keepUnitless;
	let withUnit;
	let xlinkName;
	let ariaName;
	let shouldRemoveAttribute;
	let eventKey;
	let hasListenerMap;
	let nextListener;
	let existsInNext;
	let shouldWriteStyle;
	let styleDecl;
	let xlinkLocalName;
	let attributeName;
	let serializedValue;
	let isBooleanFalse;
	let isMissingValue;
	let captureFlag;
	let styleWritten;
	let numericStyle;
	let oldStyleValue;
	let listenerMap;
	let eventName;

