		if (name == 'className') {
			name = 'class';
		}
	}

	if (name === 'style') {
		styleDecl = dom.style;
		if (typeof value == 'string') {
			styleDecl.cssText = value;
		} else {
			if (typeof oldValue == 'string') {
				styleDecl.cssText = '';
				oldValue = '';
			}

			prevStyle = snapshotStyleProps(oldValue);
			nextStyle = snapshotStyleProps(value);

			if (oldValue) {
				if (typeof prevStyle != 'string') {
					for (styleName in prevStyle) {
						existsInNext = false;
						if (value) {
							if (styleName in value) {
								existsInNext = true;
							}
						}
						if (!existsInNext) {
							if (styleName[0] === '-') {
								if (styleName[1] === '-') {
									if (styleName.length > 2) {
										styleDecl.setProperty(styleName, '');
									}
									if (styleName.length <= 2) {
										styleDecl.setProperty(styleName, '');
									}
								}
								if (styleName[1] !== '-') {
									styleDecl.setProperty(styleName, '');
								}
							} else {
								styleDecl[styleName] = '';
							}
						}
					}
				}
			}

			if (value) {
				if (typeof nextStyle != 'string') {
					for (styleName in nextStyle) {
						styleValue = value[styleName];
						oldStyleValue = oldValue ? oldValue[styleName] : undefined;
						shouldWriteStyle = !oldValue || styleValue !== oldStyleValue;
						if (shouldWriteStyle) {
							styleWritten = false;
							if (styleName[0] === '-') {
								if (styleName[1] === '-') {
									if (styleName.length > 2) {
										styleDecl.setProperty(styleName, styleValue);
										styleWritten = true;
									}
									if (styleName.length <= 2) {
										styleDecl.setProperty(styleName, styleValue);
										styleWritten = true;
									}
								}
