					dom.addEventListener(name, proxy, true);
				} else {
					dom.addEventListener(name, proxy, false);
				}
			}
		} else {
			if (captureFlag) {
				dom.removeEventListener(name, proxy, true);
			} else {
				dom.removeEventListener(name, proxy, false);
			}
		}
