			name = xlinkName;
			xlinkLocalName = name.toLowerCase();
			isMissingValue = value == null;
			isBooleanFalse = value === false;
			if (isMissingValue) {
				dom.removeAttributeNS(
					'http://www.w3.org/1999/xlink',
					xlinkLocalName
				);
			} else {
