					if (ariaName) {
						shouldRemoveAttribute = false;
					} else {
						shouldRemoveAttribute = true;
					}
				} else {
					shouldRemoveAttribute = false;
				}
			}

			if (shouldRemoveAttribute) {
				dom.removeAttribute(attributeName);
			} else {
				serializedValue = value;
				if (name === 'download') {
					dom.setAttribute(attributeName, serializedValue);
				} else if (name === 'href') {
					dom.setAttribute(attributeName, serializedValue);
				} else if (name === 'list') {
					dom.setAttribute(attributeName, serializedValue);
				} else if (name === 'form') {
					dom.setAttribute(attributeName, serializedValue);
				} else if (name === 'type') {
					dom.setAttribute(attributeName, serializedValue);
				} else if (name === 'size') {
					dom.setAttribute(attributeName, serializedValue);
				} else {
					dom.setAttribute(attributeName, serializedValue);
				}
			}
		}
